 3	
 4	public record SearchResult(SearchRequest request, List<Integer> matchIndexes) {
 5	
 6	    public SearchResult {
 7	        Objects.requireNonNull(request, "request must not be null");
 8	        Objects.requireNonNull(matchIndexes, "matchIndexes must not be null");
 9	        matchIndexes = List.copyOf(matchIndexes);
10	    }
11	
12	    public boolean hasMatches() {
13	        return !matchIndexes.isEmpty();
14	    }
15	
16	    public String joinMatchIndexes() {
17	        return joinMatchIndexes(matchIndexes);
18	    }
19	
20	    public static String joinMatchIndexes(List<Integer> matchIndexes) {
21	        Objects.requireNonNull(matchIndexes, "matchIndexes must not be null");
22	
23	        if (matchIndexes.isEmpty()) {
24	            return "";
25	        }
26	
27	        StringBuilder formattedMatches = new StringBuilder();
28	        for (int index = 0; index < matchIndexes.size(); index++) {
29	            if (index > 0) {
30	                formattedMatches.append(' ');
31	            }
32	            formattedMatches.append(matchIndexes.get(index));
33	        }
34	
35	        return formattedMatches.toString();
36	    }
37	}

