 3	public final class NaivePatternSearchTest {
 4	
 5	    private static final SearchApplication APPLICATION = SearchApplication.createDefault();
 6	
 7	    private NaivePatternSearchTest() {
 8	    }
 9	
10	    public static void main(String[] args) {
11	        assertMatches("finds repeated pattern matches",
12	                "aaba", "aabaacaadaabaaba", List.of(0, 9, 12));
13	        assertMatches("returns no matches when pattern is absent",
14	                "xyz", "aabaacaadaabaaba", List.of());
15	        assertMatches("returns no matches when pattern is longer than text",
16	                "longpattern", "short", List.of());
17	        assertMatches("supports empty patterns consistently",
18	                "", "abc", List.of(0, 1, 2, 3));
19	        assertEquals("joins match indexes for CLI output",
20	                "0 9 12", NaivePatternSearch.joinMatchIndexes(List.of(0, 9, 12)));
21	        assertSearchResult("search result keeps the originating request",
22	                new SearchRequest("banana", "ana"), List.of(1, 3));
23	        assertImmutability("search results expose an immutable match list",
24	                new SearchRequest("aaaa", "aa"));
25	        assertApplicationOutput("application formats the search output",
26	                new SearchRequest("banana", "ana"), "1 3");
27	        assertApplicationSearch("application returns the same search result contract",
28	                new SearchRequest("banana", "ana"), List.of(1, 3));
29	        assertSearchInput("uses CLI defaults when no arguments are provided",
30	                new String[0], "aabaacaadaabaaba", "aaba");
31	        assertSearchInput("allows overriding the text only",
32	                new String[] {"banana"}, "banana", "aaba");
33	        assertSearchInput("allows overriding both text and pattern",
34	                new String[] {"banana", "ana"}, "banana", "ana");
35	        assertApplicationRunFromArgs("application can execute directly from CLI args",
36	                new String[] {"banana", "ana"}, "1 3");
37	    }
38	
39	    private static void assertMatches(
40	            String scenario, String pattern, String text, List<Integer> expectedMatches) {
41	        assertEquals(scenario, expectedMatches, NaivePatternSearch.search(pattern, text));
42	    }
43	
44	    private static void assertSearchResult(
45	            String scenario, SearchRequest request, List<Integer> expectedMatches) {
46	        SearchResult result = NaivePatternSearch.search(request);
47	        assertEquals(scenario + " (request)", request, result.request());
48	        assertEquals(scenario + " (matches)", expectedMatches, result.matchIndexes());
49	        assertEquals(scenario + " (hasMatches)", !expectedMatches.isEmpty(), result.hasMatches());
50	    }
51	
52	    private static void assertImmutability(String scenario, SearchRequest request) {
53	        SearchResult result = NaivePatternSearch.search(request);
54	
55	        try {
56	            result.matchIndexes().add(99);
57	            throw new AssertionError(scenario + ": expected matchIndexes to be immutable");
58	        } catch (UnsupportedOperationException expected) {
59	        }
60	    }
61	
62	    private static void assertApplicationOutput(
63	            String scenario, SearchRequest request, String expectedOutput) {
64	        assertEquals(scenario, expectedOutput, APPLICATION.run(request));
65	    }
66	
67	    private static void assertApplicationSearch(
68	            String scenario, SearchRequest request, List<Integer> expectedMatches) {
69	        SearchResult result = APPLICATION.search(request);
70	        assertEquals(scenario + " (request)", request, result.request());
71	        assertEquals(scenario + " (matches)", expectedMatches, result.matchIndexes());
72	    }
73	
74	    private static void assertApplicationRunFromArgs(
75	            String scenario, String[] args, String expectedOutput) {
76	        assertEquals(scenario, expectedOutput, APPLICATION.run(args));
77	    }
78	
79	    private static void assertSearchInput(
80	            String scenario, String[] args, String expectedText, String expectedPattern) {
81	        SearchRequest input = NaivePatternSearchCli.parseArguments(args);
82	        assertEquals(scenario + " (text)", expectedText, input.text());
83	        assertEquals(scenario + " (pattern)", expectedPattern, input.pattern());
84	    }
85	
86	    private static void assertEquals(String scenario, Object expected, Object actual) {
87	        if (!expected.equals(actual)) {
88	            throw new AssertionError(
89	                    scenario + ": expected " + expected + " but was " + actual);
90	        }
91	    }
92	}

